selector_to_html = {"a[href=\"../half_moon/HalfMoonSection.html#pyskyfire.ducts.half_moon.HalfMoonSection.meridional_frame\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.half_moon.HalfMoonSection.meridional_frame\">\n<span class=\"sig-name descname\"><span class=\"pre\">meridional_frame</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">size</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Where each section sits on the wall, as <code class=\"docutils literal notranslate\"><span class=\"pre\">(axial,</span> <span class=\"pre\">radial,</span> <span class=\"pre\">tilt)</span></code>.</p><p>A manifold\u2019s section slides along the wall as the area law resizes it,\nand leans with whatever the wall is doing there, so it carries its own\nplacement rather than taking one from the passage. <code class=\"docutils literal notranslate\"><span class=\"pre\">tilt</span></code> is the angle\nof the section\u2019s outward direction from radial, positive toward <code class=\"docutils literal notranslate\"><span class=\"pre\">+x</span></code>,\nwhich is what a sweep needs to lay the section plane down correctly.</p></dd>", "a[href=\"#pyskyfire-ducts-port-radialport\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.port.RadialPort<a class=\"headerlink\" href=\"#pyskyfire-ducts-port-radialport\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"ResolvedRadialPort.html#pyskyfire.ducts.port.ResolvedRadialPort\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.ResolvedRadialPort\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ResolvedRadialPort</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ResolvedPort</span></code></p><p>A stub placed in machine coordinates, with the dome it leaves through.</p></dd>", "a[href=\"#pyskyfire.ducts.port.RadialPort\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.RadialPort\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RadialPort</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">Port</span></code></p><p>A straight stub leaving the dome a manifold\u2019s section is built on.</p><p>This is the chamber-manifold outlet. There is no swirl to take off\ntangentially, so the duct runs straight from the dome to its flange. It is\naimed from the ellipse centre \u2013 where the section\u2019s two axes cross, which\nis a defined point in a way the curved surface is not \u2013 and steered by a\nsingle angle in the section\u2019s own plane.</p><p class=\"rubric\">Notes</p><p>The angle both aims the stub and sizes it. How much room the dome leaves\nacross a tilted stub is not the ellipse\u2019s own semi-axis: it is how far the\npart of the ellipse that is actually passage boundary reaches across the\ndirection chosen, which closes down as the stub turns toward the fillets.\nThe stub stays centred on the ray it was aimed along, so a tilted one is\nsized by whichever side of it runs out of dome first; letting it shift off\nthat ray to take the room on the other side is a further freedom, not taken\nhere.</p></dd>", "a[href=\"PortSite.html#pyskyfire.ducts.port.PortSite\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.PortSite\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PortSite</span></span></dt><dd><p>What a passage knows about where its port attaches.</p></dd>", "a[href=\"#pyskyfire.ducts.port.RadialPort.__post_init__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.RadialPort.__post_init__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__post_init__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.port.RadialPort.resolve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.RadialPort.resolve\">\n<span class=\"sig-name descname\"><span class=\"pre\">resolve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">site</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"PortSite.html#pyskyfire.ducts.port.PortSite\" title=\"pyskyfire.ducts.port.PortSite\"><span class=\"pre\">PortSite</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"ResolvedRadialPort.html#pyskyfire.ducts.port.ResolvedRadialPort\" title=\"pyskyfire.ducts.port.ResolvedRadialPort\"><span class=\"pre\">ResolvedRadialPort</span></a></span></span></dt><dd><p>Place this port on a passage, given what the passage knows.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
